package ais.action.master.sosial.helper;
import java.math.BigDecimal; import java.util.Date; import org.hibernate.LockMode; import org.hibernate.Session; import org.hibernate.Transaction; import org.hibernate.criterion.Restrictions; import ais.database.hibernate.HibernateUtil; import ais.database.model.sosial.*;
public final class SocialReconciliationService { public SocialPaymentReconciliation record(SocialRequestContext c,String orderId,String settlementRef,Date date,BigDecimal received,BigDecimal fee){new SocialPrivilegeGuard().require(c,SocialPrivilegeGuard.FINANCE);if(received==null||received.signum()<0||received.scale()>2)throw new IllegalArgumentException("Nominal settlement tidak valid.");if(fee!=null&&(fee.signum()<0||fee.scale()>2))throw new IllegalArgumentException("Biaya settlement tidak valid.");if(settlementRef==null||settlementRef.trim().isEmpty())throw new IllegalArgumentException("Referensi settlement wajib diisi.");received=received.setScale(2);fee=fee==null?BigDecimal.ZERO:fee.setScale(2);settlementRef=settlementRef.trim();Session s=null;Transaction tx=null;try{s=HibernateUtil.openSession();tx=s.beginTransaction();PembayaranDonasi p=(PembayaranDonasi)s.createCriteria(PembayaranDonasi.class).add(Restrictions.eq("tenantKey",c.getTenantKey())).add(Restrictions.eq("gatewayOrderId",orderId)).setMaxResults(1).uniqueResult();if(p==null)throw new IllegalArgumentException("Payment tidak ditemukan.");s.lock(p,LockMode.UPGRADE);SocialPaymentReconciliation prior=(SocialPaymentReconciliation)s.createCriteria(SocialPaymentReconciliation.class).add(Restrictions.eq("tenantKey",c.getTenantKey())).add(Restrictions.eq("gateway",p.getGatewayId())).add(Restrictions.eq("settlementReference",settlementRef)).setMaxResults(1).uniqueResult();if(prior!=null){if(prior.getPayment()==null||!prior.getPayment().getId().equals(p.getId())||!sameMoney(prior.getReceivedAmount(),received)||!sameMoney(prior.getFee(),fee))throw new IllegalStateException("Referensi settlement digunakan dengan payload berbeda.");tx.commit();return prior;}SocialPaymentReconciliation r=new SocialPaymentReconciliation();r.setTenantKey(c.getTenantKey());r.setPayment(p);r.setGateway(p.getGatewayId());r.setSettlementReference(settlementRef);r.setSettlementDate(date);r.setExpectedAmount(p.getTotal());r.setReceivedAmount(received);r.setFee(fee);r.setDifference(received.subtract(p.getTotal()).setScale(2));r.setStatus(r.getDifference().signum()==0?"MATCHED":"EXCEPTION");r.setExceptionType(r.getDifference().signum()==0?null:"SETTLEMENT_MISMATCH");r.setCreatedBy(c.getActorId());s.save(r);p.setReconciliationStatus(r.getStatus());p.setSettlementBatch(settlementRef);tx.commit();return r;}catch(RuntimeException e){if(tx!=null)try{tx.rollback();}catch(Exception ignored){}throw e;}finally{if(s!=null)try{s.close();}catch(Exception ignored){}}} private boolean sameMoney(BigDecimal a,BigDecimal b){BigDecimal x=a==null?BigDecimal.ZERO:a;BigDecimal y=b==null?BigDecimal.ZERO:b;return x.compareTo(y)==0;} }
